#include <iostream>
#include <fstream>
#include <string>
#include <vector>
using namespace std;

int nwd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int skrot(int n) {
    string s = to_string(n);
    string wynik = "";
    for (char c : s) {
        int cyfra = c - '0';
        if (cyfra % 2 == 1) {
            wynik += c;
        }
    }
    if (wynik.empty()) return 0;
    return stoi(wynik);
}

int main() {
    ifstream plik("dane.txt");
    int n;
    vector<int> liczby;
    while (plik >> n) liczby.push_back(n);

    cout << "a) Skroty:" << endl;
    vector<int> skroty;
    for (int x : liczby) {
        int sk = skrot(x);
        skroty.push_back(sk);
        cout << x << " -> " << sk << endl;
    }

    cout << endl << "b) Liczby z NWD(liczba, skrot) = 7:" << endl;
    int ile = 0;
    for (int i = 0; i < liczby.size(); i++) {
        if (skroty[i] > 0) {
            int g = nwd(liczby[i], skroty[i]);
            if (g == 7) {
                cout << liczby[i] << " -> skrot " << skroty[i]
                     << ", NWD(" << liczby[i] << ", " << skroty[i]
                     << ") = " << g << " -> TAK" << endl;
                ile++;
            }
        }
    }
    cout << "Ilosc: " << ile << endl;
    return 0;
}
```

